SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition = 'brand_new';

SELECT COUNT(*) AS nintendo_switch_count
FROM nlq.listings
WHERE (title ILIKE '%nintendo switch%' OR description ILIKE '%nintendo switch%');

SELECT COUNT(*) AS total_listings
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS board_game_count
FROM nlq.listings
WHERE category ILIKE '%board%';

SELECT COUNT(*) AS monitor_count
FROM nlq.listings
WHERE (title ILIKE '%27 inch monitor%' OR description ILIKE '%27 inch monitor%');

SELECT round(100.0 * COUNT(*) FILTER (WHERE rent_price_per_week IS NOT NULL) / COUNT(*), 2) AS rent_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY l.rent_price_per_week) AS median_weekly_rent
FROM nlq.listings l
WHERE l.rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_count
FROM nlq.listings
WHERE meetup_spot ILIKE '%pickup only%';

SELECT COUNT(*) AS listings_since_october_1
FROM nlq.listings
WHERE listed_at >= '2026-10-01'::date;

SELECT COUNT(*) AS five_star_ratings_received
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT MIN(rating) AS worst_rating
FROM nlq.my_reviews
WHERE direction = 'received';

SELECT COUNT(*) AS removed_count
FROM nlq.my_listings
WHERE status = 'removed';

SELECT COALESCE(SUM(CASE WHEN my_role = 'buyer' THEN agreed_price ELSE 0 END), 0) AS total_spent
FROM nlq.my_deals
WHERE status = 'completed';

SELECT COUNT(DISTINCT category) AS distinct_categories
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

select coalesce(sum(case when my_role = 'seller' then agreed_price else 0 end), 0) - coalesce(sum(case when my_role = 'buyer' then agreed_price else 0 end), 0) as net_gain
from nlq.my_deals
where status = 'completed';

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT COUNT(*) AS reserved_count
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition = 'like_new';

SELECT COUNT(*) AS suspended_accounts
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_reports
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_one_star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS reports_against_listings
FROM nlq.reports
WHERE target_type = 'listing';

SELECT DISTINCT name AS off_campus_spot
FROM nlq.meetup_spots
WHERE area = 'off campus';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT ROUND(AVG(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       ROUND(AVG(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS conversations_with_buyer_more_messages
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE rating = 5) / COUNT(*), 2) AS five_star_share_percent
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT COUNT(*) AS students_never_posted
FROM nlq.students s
WHERE NOT EXISTS (
    SELECT 1 FROM nlq.listings_all la
    WHERE la.seller_id = s.student_id
);

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'removed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS removed_percentage
FROM nlq.listings_all
WHERE condition = 'good';

SELECT round(100.0 * COUNT(*) FILTER (WHERE (resolved_at - filed_at) < '48 hours'::interval) / COUNT(*), 2) AS percent_closed_48h
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS zero_bookmarked_items
FROM nlq.listings_all la
WHERE NOT EXISTS (
  SELECT 1 FROM nlq.saved_items si
  WHERE si.item_id = la.item_id
);

select round(avg(extract(epoch from c.first_seller_reply_at - c.started_at) / 3600)::numeric, 2) as avg_reply_hours
from nlq.conversations c
where c.first_seller_reply_at is not null;

select count(*) as listings_saved_by_at_least_5_students_never_sold
from (
  select s.item_id, count(distinct s.student_id) as saved_by_count
  from nlq.saved_items s
  join nlq.listings_all l on s.item_id = l.item_id
  where l.status = 'sold'
    group by s.item_id
) sub
where saved_by_count >= 5;
